            if f.startswith('.'):
                print(f"  Hidden file found: {f}")
            # Check if it's a directory
            elif os.path.isdir(file_path):
                print(f"  Directory found (should be file): {f}")
            # Try to open the image to see if it's valid
            else:
                try:
                    with Image.open(file_path) as img:
                        pass  # Successfully opened
                except Exception as e:
                    print(f"  Invalid image file: {f} - Error: {e}")"}

